void db_scp(void  *entity)
/*
Output a brief description of the given entity (which is assumed to start with
a source correspondence).
*/
{
  a_source_correspondence_ptr  scp = (a_source_correspondence_ptr)entity;
  a_symbol_ptr                 sym = (a_symbol_ptr)scp->assoc_info;
  a_line_number                line;
  a_const_char                 *file_name, *full_name;
  a_boolean                    at_end_of_source;

  if (scp->assoc_info != NULL) {
    db_symbol_name(sym);
    if (symbol_is(sym, sk_variable)) {
      a_variable_ptr  var = sym->variant.variable.ptr;
      if (var->template_info != NULL &&
          var->template_info->template_arg_list != NULL) {
        db_template_arg_list(var->template_info->template_arg_list);
      }  /* if */
    }  /* if */
    fprintf(f_debug, " (%s)", symbol_kind_names[(int)sym->kind]);
  } else {
    db_name(scp);
  }  /* if */
  (void)conv_seq_to_file_and_line(scp->decl_position.seq, &file_name,
                                  &full_name, &line, &at_end_of_source);
  if (line != 0) {
    fprintf(f_debug, " in file %s (line %lu)\n", file_name,
            (unsigned long)line);
  } else {
    fprintf(f_debug, " (built-in; line %lu)\n", (unsigned long)line);
  }  /* if */
}  /* db_scp */


void db_entity_info(char             *entry,
                    an_il_entry_kind kind)
/*
Display the name of the indicated entity (one that begins with a
source correspondence field and has kind "kind") along with some related
information, such as its address and translation unit.
*/
{
  char      *copy_addr = NULL;
  a_boolean has_defn = FALSE, show_defn_state = FALSE;

  if (entry == NULL) {
    fprintf(f_debug, "<null pointer>\n");
  } else {
#if MAINTAIN_ALLOCATION_SEQUENCE_NUMBER
    fprintf(f_debug, "(seq %lu) ",
                     il_entry_prefix_of(entry).alloc_seq_number);
#endif /* MAINTAIN_ALLOCATION_SEQUENCE_NUMBER */
    fprintf(f_debug, "%s", il_entry_kind_names[(int)kind]);
    if (kind == iek_type) {
      fprintf(f_debug, " ");
      db_abbreviated_type((a_type_ptr)entry);
    } else if (source_corresp_for_il_entry(entry, kind) != NULL) {
      fprintf(f_debug, " %s",
                       db_name_str((a_source_correspondence *)entry, kind));
    }  /* if */
    fprintf(f_debug, "\n");
    fprintf(f_debug, "address = %p", (a_void_ptr)entry);
    fprintf(f_debug, ", in %s trans unit", in_secondary_trans_unit(entry) ?
                                               "secondary" : "primary");
    fprintf(f_debug, ", in %s scope", in_file_scope(entry) ?
                                               "file" : "function");
#if DO_IL_LOWERING
    fprintf(f_debug, ", %slowered", visited_yet(entry) ?  "" : "un-");
#endif /* DO_IL_LOWERING */
    if (kind == iek_type) {
      a_type_ptr type = (a_type_ptr)entry;
      if (is_immediate_class_type(type)) {
        show_defn_state = TRUE;
        has_defn = class_type_has_body(type);
      } else if (is_immediate_enum_type(type)) {
        show_defn_state = TRUE;
        has_defn = !is_incomplete_type(type);
      }  /* if */
    } else if (kind == iek_routine) {
      a_routine_ptr rout = (a_routine_ptr)entry;
      show_defn_state = TRUE;
      has_defn = (rout->function_def_number != NULL_function_def_number);
    } else if (kind == iek_variable) {
      a_variable_ptr var = (a_variable_ptr)entry;
      show_defn_state = TRUE;
      has_defn = (var->storage_class == (a_storage_class)sc_unspecified);
    }  /* if */
    if (show_defn_state) {
      fprintf(f_debug, ", %s definition", has_defn ? "has" : "no");
    }  /* if */
    fprintf(f_debug, "\n");
    if (in_front_end) {
      a_source_correspondence  *scp = source_corresp_for_il_entry(entry, kind);
      a_trans_unit_corresp_ptr tucp =
                                (scp == NULL) ? NULL : scp->trans_unit_corresp;
      if (tucp != NULL) {
        /* Display the correspondence information. */
        fprintf(f_debug, "corresp = %p, canonical = %p, primary = %p\n",
                (a_void_ptr)tucp, (a_void_ptr)tucp->canonical,
                (a_void_ptr)tucp->primary);
      }  /* if */
      if (in_secondary_trans_unit(entry) && in_file_scope(entry)) {
        copy_addr = trans_unit_copy_address_of(entry);
        fprintf(f_debug, "copy address = %p", (a_void_ptr)copy_addr);
        /* Check for a second level copy address. */
        if (copy_addr != NULL && in_secondary_trans_unit(copy_addr)) {
          copy_addr = trans_unit_copy_address_of(copy_addr);
          fprintf(f_debug, ", %p", (a_void_ptr)copy_addr);
        }  /* if */
        fprintf(f_debug, "\n");
      }  /* if */
    }  /* if */
  }  /* if */
}  /* db_entity_info */


void db_entity_list(an_il_entity_list_entry  *list)
/*
Output the summarized contents of the given IL entity list.
*/
{
  while (list != NULL) {
    db_entity_info(list->entity.ptr, list->entity.kind);
    list = list->next;
    if (list != NULL) {
      fprintf(f_debug, "\n\n");
    }  /* if */
  }  /* while */
}  /* db_entity_list */


