void set_complex_constant(a_float_kind float_kind,
                          a_const_char *real,
                          a_const_char *imag,
                          a_constant   *con)
/*
Fill in the constant "con" as a complex constant of kind "float_kind" with
"real" and "imag" components.  Should only be used with floating point strings
that are known to be representable.
*/
{
  an_internal_float_value float_value;
  a_boolean               err;

  clear_constant(con, (a_constant_repr_kind)ck_complex);
  con->type = complex_type(float_kind);
  fp_string_to_float(float_kind, real, &float_value, &err);
  check_assertion(!err);
  con->variant.complex_value->real = float_value;
  fp_string_to_float(float_kind, imag, &float_value, &err);
  check_assertion(!err);
  con->variant.complex_value->imag = float_value;
}  /* set_complex_constant */

#endif /* C99_IL_EXTENSIONS_SUPPORTED */

a_type_ptr string_literal_type(a_character_kind  kind,
                               a_targ_size_t     num_chars)
/*
Make or find an entry for the type of a string literal with the given number
of characters and the given character kind.  Return a pointer to this type.
Multiple calls with the same value of num_chars return the same type entry
if num_chars <= MAX_TRACKED_STRING_TYPE_LENGTH and the calls occur in the
front end proper (i.e., when in_front_end is TRUE).
*/
{
  a_type_ptr  result;

  if (num_chars <= MAX_TRACKED_STRING_TYPE_LENGTH && in_front_end &&
      string_types[kind][num_chars] != NULL) {
    /* The type has previously been created, and can be reused. */
    result = string_types[kind][num_chars];
  } else {
    a_type_ptr  elem_type = character_type(kind);
    if (string_literals_are_const) {
      /* The element type is const (this is the case in standard C++, but
         was not the case in the C++ ARM). */
      elem_type = make_qualified_type(elem_type, TQ_CONST);
    }  /* if */
    result = alloc_type((a_type_kind)tk_array);
    result->variant.array.element_type = elem_type;
    result->variant.array.variant.number_of_elements = num_chars;
    if (num_chars == 0) {
      result->variant.array.bound_is_zero = TRUE;
    }  /* if */
    set_type_size(result);
    if (num_chars <= MAX_TRACKED_STRING_TYPE_LENGTH && in_front_end) {
      string_types[kind][num_chars] = result;
    }  /* if */
#if ORPHAN_PROCESSING_NEEDED
    /* Record the type entry as an orphan in case it is discarded now
       and then found again in a later phase (e.g., IL lowering). */
    add_orphaned_file_scope_il_entry((char *)result,
                                     (an_il_entry_kind)iek_type);
#endif /* ORPHAN_PROCESSING_NEEDED */
  }  /* if */
  return result;
}  /* string_literal_type */


a_type_ptr string_type(a_targ_size_t  num_chars)
/*
Return the type of an ordinary character string of the given length.  Note
that this should not be implemented as a forwarding macro if the code is
to be compiled as C++ because "string_type" is an identifier defined by the
C++ standard library.
*/
{
    return string_literal_type((a_character_kind)chk_char, num_chars);
}  /* string_type */


