a_boolean has_nonreal_parent_type(a_source_correspondence	*scp)
/*
Return TRUE if the entity specified by scp has a parent type that is
a template parameter type or nonreal class.
*/
{
  a_boolean	result = FALSE;

  if (scp->is_class_member) {
    a_type_ptr  parent_type = scp_parent_class(scp);
    if (is_immediate_class_type(parent_type)) {
      result = parent_type->variant.class_struct_union.is_nonreal_class;
    } else if (parent_type->kind == (a_type_kind)tk_template_param) {
      result = TRUE;
    }  /* if */
  }  /* if */
  return result;
}  /* has_nonreal_parent_type */


void add_to_templates_list(a_template_ptr  tp,
                           a_scope_depth   scope_depth)
/*
Add the IL template entry pointed to by tp to the indicated scope.
*/
{
  a_scope_stack_entry_ptr     ssep;
  a_scope_ptr                 sp;
  a_scope_pointers_block_ptr  pointers_block;

  assert_is_valid_scope_depth(scope_depth);
  ssep = &scope_stack[scope_depth];
  if (!prototype_instantiations_in_il &&
      (ssep->in_prototype_instantiation ||
       has_nonreal_parent_type(&tp->source_corresp))) {
    /* We are not going to record the indicated scope (because it belongs to
       a prototype instantiation), but the given template must go on a list
       somewhere because assoc_template fields may point to it.
       Add it to the file scope.  Later, during the file scope wrapup,
       the file scope templates list will be scanned, and the parent pointer
       of templates from prototype instantiations will be cleared. */
    ssep = &scope_stack[DEPTH_OF_FILE_SCOPE];
  }  /* if */
  sp = ensure_il_scope_exists(ssep);
  check_assertion_str(sp != NULL, "add_to_templates_list: NULL IL scope");
  pointers_block = assoc_pointers_block_of(ssep);
  if (sp->templates == NULL) {
    sp->templates = tp;
  } else {
    pointers_block->last_template->next = tp;
  }  /* if */
  pointers_block->last_template = tp;
  tp->next = NULL;
  /* The parent scope pointer is weird for templates, since each declaration
     gets a separate template entry that goes on the list wherever it appears.
     The parent pointer is usually set already, and if so we leave it
     alone. */
  if (parent_scope_of(tp) == NULL && 
      !tp->source_corresp.parent_via_local_scope_ref) {
    /* The parent_via_local_scope_ref is used to suppress this in certain error
       cases. */
    set_parent_scope(&tp->source_corresp, iek_template, sp);
  }  /* if */
}  /* add_to_templates_list */

#if MICROSOFT_EXTENSIONS_ALLOWED

void add_to_ms_attributes_list(an_ms_attribute_ptr	msap,
                               a_scope_depth		scope_depth)
/*
Add the Microsoft attribute entry pointed to by msap to the indicated scope
(or the nearest enclosing scope for template declaration scopes).
*/
{
  a_scope_stack_entry_ptr  ssep;
  a_scope_ptr              sp;
  a_scope_pointers_block_ptr  pointers_block;

  assert_is_valid_scope_depth(scope_depth);
  ssep = &scope_stack[scope_depth];
  /* Skip template declaration and instantiation context scopes. */
  while (scope_is(ssep, sck_template_declaration) ||
         scope_is(ssep, sck_instantiation_context)) {
    ssep = previous_scope_of(ssep);
  }  /* while */
  sp = ensure_il_scope_exists(ssep);
  check_assertion_str(sp != NULL, "add_to_ms_attributes_list: NULL IL scope");
  pointers_block = assoc_pointers_block_of(ssep);
  if (sp->ms_attributes == NULL) {
    sp->ms_attributes = msap;
  } else {
    pointers_block->last_ms_attribute->next = msap;
  }  /* if */
  pointers_block->last_ms_attribute = msap;
  msap->next = NULL;
}  /* add_to_ms_attributes_list */


a_routine_ptr selectively_overridden_function(a_routine_ptr  rp)
/*
If rp is a member function that was declared to selectively override a known
function, return that overridden function.  Otherwise, return NULL.  In
particular, if rp is a member of a prototype instantiation declared to
override a member from a template-dependent (i.e., unknown) base class, NULL
will be returned.
Selective overriding is a Microsoft extension.  For example:
  struct B1 { virtual int f() = 0; };
  struct B2 { virtual int f() = 0; };
  struct D: B1, B2 {
    int B1::f() { return 1; }  // Selectively overrides B1::f (not B2::f).
    int B2::f() { return 2; }  // Selectively overrides B2::f (not B1::f).
  };
*/
{
  a_routine_ptr  result = NULL;

  if (rp->overridden_functions != NULL) {
    a_tagged_pointer  ep = rp->overridden_functions->entity;
    if ((an_il_entry_kind)ep.kind == iek_routine) {
      result = (a_routine_ptr)ep.ptr;
    }  /* if */
    check_assertion(rp->overridden_functions->next == NULL);
  }  /* if */
  return result;
}  /* selectively_overridden_function */

#endif /* MICROSOFT_EXTENSIONS_ALLOWED */

