a_type_ptr init_predeclared_class(a_type_kind          kind,
                                  a_const_char         *name)
/*
Create a type entry for a predeclared class of the specified kind.  It is
given the name indicated and a symbol is created, but the symbol is not
entered into the symbol table.
*/
{
  a_type_ptr  predeclared_type;

  predeclared_type = alloc_type(kind);
  if (!C_mode()) {
    /* Default name-linkage for classes is C++ external linkage. */
    predeclared_type->source_corresp.name_linkage =
                                (a_name_linkage_kind)nlk_cplusplus_external;
  }  /* if */
  make_symbol_for_predeclared_type(predeclared_type, name);
  return predeclared_type;
}  /* init_predeclared_class */


void enter_predeclared_class(a_type_ptr         predeclared_type,
                             a_scope_depth      scope_depth,
                             a_source_position  *pos)
/*
Enter the given predeclared type (e.g., type_info) at the given scope depth
with the given source position.
*/
{
  a_symbol_ptr  sym = symbol_for(predeclared_type);
  a_namespace_ptr  nsp = NULL;

  switch (scope_stack[scope_depth].kind) {
    case sck_file:
      nsp = NULL;
      break;
    case sck_namespace:
    case sck_namespace_extension:
      nsp = scope_stack[scope_depth].il_scope->variant.assoc_namespace;
      break;
    default:
      unexpected_condition();
  }  /* switch */
  sym->decl_position = *pos;
  reenter_symbol(sym, scope_depth, /*suppress_error=*/FALSE);
  /* Call set_source_corresp again to get everything in sync. */
  set_source_corresp(&(predeclared_type->source_corresp), sym);
  set_namespace_membership(sym, &(predeclared_type->source_corresp), nsp);
  /* The referenced flag may have been reset by set_source_corresp. */
  predeclared_type->source_corresp.referenced = sym->referenced;
  add_to_types_list(predeclared_type, scope_depth);
}  /* enter_predeclared_class */


a_targ_alignment alignment_of_variable(a_variable_ptr  vp)
/*
Return the alignment of the given variable.  In GNU and Microsoft modes, this
may be affected by attributes specified on the variable declaration.  In some
rare cases (e.g., in GNU 3.0 compatibility mode), the result may be different
from that implied by the alignof operator applied to the variable (see
scan_alignof_operator for details).
*/
{
  a_targ_alignment  result;

  if (vp->alignment != 0) {
    /* Alignment was specified explicitly on the variable declaration. */
    result = vp->alignment;
  } else {
    result = alignment_of_type(vp->type);
  }  /* if */
  return result;
}  /* alignment_of_variable */
#endif /* !STANDALONE_UTILITY_PROGRAM */


an_attribute_ptr find_attribute(an_attribute_kind  kind,
                                an_attribute_ptr   attributes)
/*
Return the first attribute of the given kind in the given list of attributes,
or NULL if there is no such item.
*/
{
  an_attribute_ptr  ap;

  for (ap = attributes; ap != NULL; ap = ap->next) {
    if (ap->kind == kind) break;
  }  /* for */
  return ap;
}  /* find_attribute */

#if GNU_FUNCTION_MULTIVERSIONING

an_attribute_ptr find_last_target_attribute(an_attribute_ptr attributes)
/*
Return the last "target" attribute in the given list of attributes; this seems
to match the GNU behavior (it only acts on the last "target" attribute in
a set).  As this call is typically made before attribute checking has occurred,
only consider string attributes (diagnostics will be issued when the
attributes are later processed for the non-string cases).
*/
{
  an_attribute_ptr  ap, last = NULL;

  for (ap = attributes; ap != NULL; ap = ap->next) {
    if (ap->kind == ak_target) {
      an_attribute_arg_ptr  aap = ap->arguments;
      if (aap->kind == (an_attribute_arg_kind)aak_raw_token &&
          aap->variant.token[0] == '"') {
        last = ap;
      }  /* if */
    }  /* if */
  }  /* for */
  return last;
}  /* find_last_target_attribute */

#endif /* GNU_FUNCTION_MULTIVERSIONING */

